{"implementation": "def solve(case):
    import json
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    # Build mutual reachability edges
    edges = []
    for a, b, d in distances:
        w = max(core[a], core[b], d)
        # canonicalize order for deterministic tie-breaking
        if a <= b:
            edges.append((w, a, b))
        else:
            edges.append((w, b, a))

    # Sort primary by weight, then first endpoint, then second endpoint
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    needed = len(nodes) - 1

    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == needed:
                break

    if len(mst_edges) != needed:
        raise ValueError('Graph is disconnected, cannot form MST')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
